-- ============================================================
-- PAKISTAN LOCATION DATA SEED - COMPREHENSIVE
-- Provinces, Districts, Cities and Areas
-- Total: 7 Provinces, 160 Districts, 159 seeded cities (+146,772 in
--        pakistan_cities_all.sql), 4,432 Areas (Lahore 1,453 + Kasur 1,656)
-- ============================================================

-- Drop existing tables if needed (uncomment for fresh install)
-- DROP TABLE IF EXISTS venues CASCADE;
-- DROP TABLE IF EXISTS areas CASCADE;
-- DROP TABLE IF EXISTS cities CASCADE;
-- DROP TABLE IF EXISTS provinces CASCADE;

-- ============================================================
-- 1. PROVINCES
-- ============================================================
CREATE TABLE IF NOT EXISTS provinces (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    code VARCHAR(10) UNIQUE,
    country VARCHAR(100) DEFAULT 'Pakistan'
);

INSERT INTO provinces (id, name, code) VALUES
(1, 'Punjab', 'PB'),
(2, 'Sindh', 'SD'),
(3, 'Khyber Pakhtunkhwa', 'KP'),
(4, 'Balochistan', 'BA'),
(5, 'Islamabad Capital Territory', 'ICT'),
(6, 'Azad Jammu & Kashmir', 'AJK'),
(7, 'Gilgit-Baltistan', 'GB')
ON CONFLICT (id) DO NOTHING;

