-- Extra city columns, filled by pakistan_cities_all.sql.
ALTER TABLE cities ADD COLUMN IF NOT EXISTS district_id INT REFERENCES districts(id);
ALTER TABLE cities ADD COLUMN IF NOT EXISTS geoname_id  BIGINT;
ALTER TABLE cities ADD COLUMN IF NOT EXISTS kind        VARCHAR(24);
ALTER TABLE cities ADD COLUMN IF NOT EXISTS search_key  TEXT
    GENERATED ALWAYS AS (btrim(regexp_replace(lower(name), '[^a-z0-9]+', ' ', 'g'))) STORED;

