-- 3. AREAS / LOCALITIES / TEHSILS
-- ============================================================
CREATE TABLE IF NOT EXISTS areas (
    id SERIAL PRIMARY KEY,
    city_id INT REFERENCES cities(id),
    name VARCHAR(100) NOT NULL,
    source VARCHAR(20) DEFAULT 'seeded',
    kind VARCHAR(20),                  -- 'neighbourhood' | 'village'
    latitude DECIMAL(10, 8),
    longitude DECIMAL(11, 8),
    -- Alternate spellings people actually type: 'Lidher' for 'Lidhar',
    -- 'Bhatta Chowk' for 'Bhata Chowk'. Searched alongside name.
    aliases TEXT[] NOT NULL DEFAULT '{}',
    -- Normalised match key: lowercased, punctuation folded to single spaces.
    -- Stops 'D.H.A. Phase 5' being inserted next to 'DHA Phase 5'.
    search_key TEXT GENERATED ALWAYS AS (
        btrim(regexp_replace(lower(name), '[^a-z0-9]+', ' ', 'g'))
    ) STORED
);

