-- ---- Lahore: alternate spellings people actually type.
--      Search `name` OR `aliases`, otherwise someone typing the spelling they
--      know ("Lidher", "Bhatta Chowk") gets no result for a row that exists.
UPDATE areas SET aliases = v.alt FROM (VALUES
  ('Lidher', ARRAY['Lidhar','Lidhar Kalan']),
  ('Dera Chahl',          ARRAY['Dera Chahal','Dera Chahl']),
