-- ============================================================
-- 4. INDEXES FOR PERFORMANCE
-- ============================================================
CREATE INDEX IF NOT EXISTS idx_cities_province ON cities(province_id);
CREATE INDEX IF NOT EXISTS idx_cities_district ON cities(district_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_cities_geoname ON cities(geoname_id) WHERE geoname_id IS NOT NULL;
-- Type-ahead over 147k towns and villages, scoped to the chosen province.
CREATE INDEX IF NOT EXISTS idx_cities_search ON cities(province_id, search_key text_pattern_ops);
CREATE INDEX IF NOT EXISTS idx_districts_province ON districts(province_id);
CREATE INDEX IF NOT EXISTS idx_areas_city ON areas(city_id);
CREATE INDEX IF NOT EXISTS idx_areas_source ON areas(source);

-- The duplicate guard: one row per (city, normalised name). This is what stops
-- 'D.H.A. Phase 5' being inserted alongside 'DHA Phase 5' as users add areas.
CREATE UNIQUE INDEX IF NOT EXISTS idx_areas_city_key ON areas(city_id, search_key);
-- Type-ahead over the canonical name.
CREATE INDEX IF NOT EXISTS idx_areas_search_key ON areas(city_id, search_key text_pattern_ops);
-- Alternate spellings, searched alongside the name.
CREATE INDEX IF NOT EXISTS idx_areas_aliases ON areas USING GIN (aliases);
-- Neighbourhoods before villages in the picker.
CREATE INDEX IF NOT EXISTS idx_areas_kind ON areas(city_id, kind);

-- ============================================================
-- 5. PENDING AREAS TABLE (for user suggestions)
-- ============================================================
CREATE TABLE IF NOT EXISTS pending_areas (
    id SERIAL PRIMARY KEY,
    city_id INT REFERENCES cities(id),
    name VARCHAR(100) NOT NULL,
    suggested_by UUID,
    status VARCHAR(20) DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT NOW()
);

-- ============================================================
-- 6. SAMPLE QUERIES
-- ============================================================

-- Get all provinces:
-- SELECT * FROM provinces ORDER BY name;

-- Get cities by province:
-- SELECT * FROM cities WHERE province_id = 1 ORDER BY name;

-- Get areas by city:
-- SELECT * FROM areas WHERE city_id = 1 ORDER BY name;

-- Get full hierarchy:
-- SELECT p.name AS province, c.name AS city, a.name AS area, a.source
-- FROM provinces p
-- JOIN cities c ON c.province_id = p.id
-- LEFT JOIN areas a ON a.city_id = c.id
-- WHERE c.name = 'Lahore'
-- ORDER BY a.name;

-- Count stats:
-- SELECT 
--     (SELECT COUNT(*) FROM provinces) as total_provinces,
--     (SELECT COUNT(*) FROM cities) as total_cities,
--     (SELECT COUNT(*) FROM areas) as total_areas;
